import { useState, type FormEvent } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

export type SignupValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

export type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyValues: SignupValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const SignupWizard = ({ onSubmit }: SignupWizardProps) => {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(emptyValues);

  const setField = (field: keyof SignupValues) => (event: { target: { value: string } }) =>
    setValues((current) => ({ ...current, [field]: event.target.value }));

  const isLast = step === steps.length - 1;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLast) {
      onSubmit(values);
      return;
    }
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  const summary: Array<[string, string]> = [
    ['Имя', values.name],
    ['Электронная почта', values.email],
    ['Телефон', values.phone],
    ['Город', values.city],
    ['Улица и дом', values.street],
    ['Индекс', values.zip],
  ];

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 16px)' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 12px)' }}>
          <JxInputField
            label="Имя"
            required
            value={values.name}
            onChange={setField('name')}
            placeholder="Как к вам обращаться"
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={values.email}
            onChange={setField('email')}
            helperText="На неё придёт письмо с подтверждением"
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={values.phone}
            onChange={setField('phone')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 12px)' }}>
          <JxInputField label="Город" required value={values.city} onChange={setField('city')} />
          <JxInputField
            label="Улица и дом"
            required
            value={values.street}
            onChange={setField('street')}
          />
          <JxInputField
            label="Индекс"
            inputMode="numeric"
            value={values.zip}
            onChange={setField('zip')}
            helperText="Шесть цифр"
          />
        </div>
      )}

      {step === 2 && (
        <dl
          style={{
            display: 'grid',
            gridTemplateColumns: 'minmax(0, 1fr) minmax(0, 1fr)',
            gap: 'var(--jx-gap, 12px)',
            margin: 0,
            padding: 'var(--jx-gap, 16px)',
            background: 'var(--jx-surface-2)',
            border: '1px solid var(--jx-border)',
            borderRadius: 'var(--jx-r)',
          }}
        >
          {summary.map(([label, value]) => (
            <div key={label} style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              <dt style={{ color: 'var(--jx-text-3)' }}>{label}</dt>
              <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{value || '—'}</dd>
            </div>
          ))}
        </dl>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-gap, 8px)' }}>
        <JxButton
          variant="ghost"
          type="button"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
};

export default SignupWizard;

